use std::sync::{Arc, Mutex};
use std::time::Duration;

async fn bump(state: Arc&lt;Mutex&lt;u64&gt;&gt;) {
    let mut n = state.lock().unwrap();
    tokio::time::sleep(Duration::from_millis(1)).await; // guard still alive here
    *n += 1;
}

