Writing a Clean main.rs Dispatcher
// src/main.rs
use anyhow::Result;
use clap::Parser;
use std::process::ExitCode;

mod cli;

fn main() -&gt; ExitCode {
    let args = cli::Cli::parse();

    // Initialize structured logging
    tracing_subscriber::fmt::init();

    if let Err(err) = run(args) {
        eprintln!("{:#}", err);
        return ExitCode::FAILURE;
    }

    ExitCode::SUCCESS
}

fn run(args: cli::Cli) -&gt; Result&lt;()&gt; {
    match args.command {
        cli::Commands::Scan(opts) =&gt; mycli::scan(opts)?,
        cli::Commands::Build(opts) =&gt; mycli::build(opts)?,
    }
    Ok(())
