The #[tokio::main] Attribute
The #[tokio::main] macro sets up the multi-threaded asynchronous executor and starts the root future:
use anyhow::Result;
use reqwest::Client;
use std::time::Duration;

#[tokio::main]
async fn main() -&gt; Result&lt;()&gt; {
    let client = Client::builder()
        .timeout(Duration::from_secs(5))
        .build()?;

    let response = client
        .get("https://httpbin.org/status/200")
        .send()
        .await?;

    println!("Async response status: {}", response.status());
    Ok(())
}

Bounded Concurrency with tokio::sync::Semaphore
A common CLI mistake is launching thousands of unbounded concurrent network tasks, exhausting local socket descriptors or triggering remote rate limits (HTTP 429). Use a Semaphore to bound concurrent flight:
use std::sync::Arc;
use tokio::sync::Semaphore;
use anyhow::Result;

async fn fetch_urls(urls: Vec&lt;String&gt;) -&gt; Result&lt;()&gt; {
    let client = reqwest::Client::new();
    // Allow at most 10 concurrent HTTP requests
    let semaphore = Arc::new(Semaphore::new(10));
    let mut handles = Vec::new();

    for url in urls {
        let permit = semaphore.clone().acquire_owned().await?;
        let client = client.clone();

        handles.push(tokio::spawn(async move {
            let res = client.get(&url).send().await;
            drop(permit); // Release slot for next request
            (url, res.map(|r| r.status()))
        }));
    }

    for handle in handles {
        let (url, result) = handle.await?;
        println!("{url} -&gt; {:?}", result);
    }

    Ok(())
}

Graceful Cancellation via tokio::select!
Listen for OS interrupt signals (Ctrl+C) while long-running network or disk jobs are active:
#[tokio::main]
async fn main() {
    tokio::select! {
        _ = tokio::signal::ctrl_c() =&gt; {
            eprintln!("\nReceived Ctrl+C, gracefully terminating worker tasks...");
        }
        res = run_worker() =&gt; {
            println!("Worker completed with: {:?}", res);
        }
    }
}

async fn run_worker() -&gt; Result&lt;(), ()&gt; {
    tokio::time::sleep(std::time::Duration::from_secs(60)).await;
    Ok(())
}

Raw Mode and Alternate Screen Lifecycle
A TUI must enter raw mode (disabling line buffering and OS echo) and switch to an alternate screen buffer, restoring the user’s previous terminal state upon exit:
use std::io::{self, stdout};
use crossterm::{
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::prelude::*;

pub struct TerminalGuard;

impl TerminalGuard {
    pub fn enter() -&gt; io::Result&lt;Terminal&lt;CrosstermBackend&lt;io::Stdout&gt;&gt;&gt; {
        enable_raw_mode()?;
        let mut stdout = stdout();
        execute!(stdout, EnterAlternateScreen)?;
        let backend = CrosstermBackend::new(stdout);
        Terminal::new(backend)
    }
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen);
    }
}

Immediate-Mode Rendering Loop
ratatui recalculates and renders the interface every frame based on the current application state:
use ratatui::{
    layout::{Constraint, Direction, Layout},
    style::{Color, Style},
    widgets::{Block, Borders, Paragraph},
    Frame,
};

struct AppState {
    counter: usize,
    status_message: String,
}

fn ui(frame: &mut Frame, state: &AppState) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(3),
        ])
        .split(frame.size());

    let header = Paragraph::new("Rust Production TUI Monitor")
        .style(Style::default().fg(Color::Cyan))
        .block(Block::default().borders(Borders::ALL));
    frame.render_widget(header, chunks[0]);

    let body = Paragraph::new(format!("Tasks Processed: {}", state.counter))
        .block(Block::default().title("Active Workload").borders(Borders::ALL));
    frame.render_widget(body, chunks[1]);

    let footer = Paragraph::new(state.status_message.as_str())
        .style(Style::default().fg(Color::DarkGray))
        .block(Block::default().borders(Borders::ALL));
    frame.render_widget(footer, chunks[2]);
}

Standard Directory Paths with dirs
Different operating systems adhere to different path conventions: - Linux: ~/.config/mycli (XDG Base Directory standard) - macOS: ~/Library/Application Support/mycli - Windows: %APPDATA%\mycli
The dirs crate discovers these paths safely across all platforms:
[dependencies]
dirs = "5.0"
serde = { version = "1.0", features = ["derive"] }
toml = "0.8"
use std::path::PathBuf;
use serde::{Deserialize, Serialize};
use std::fs;
use anyhow::{Context, Result};

#[derive(Serialize, Deserialize, Debug)]
pub struct AppConfig {
    pub api_endpoint: String,
    pub timeout_seconds: u64,
    pub verbose: bool,
}

impl Default for AppConfig {
    fn default() -&gt; Self {
        Self {
            api_endpoint: "https://api.example.com".to_string(),
            timeout_seconds: 30,
            verbose: false,
        }
    }
}

pub fn get_config_path() -&gt; Option&lt;PathBuf&gt; {
    dirs::config_dir().map(|p| p.join("mycli").join("config.toml"))
}

pub fn load_or_create_config() -&gt; Result&lt;AppConfig&gt; {
    let path = match get_config_path() {
        Some(p) =&gt; p,
        None =&gt; return Ok(AppConfig::default()),
    };

    if !path.exists() {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let default_config = AppConfig::default();
        let toml_str = toml::to_string_pretty(&default_config)?;
        fs::write(&path, toml_str)?;
        return Ok(default_config);
    }

    let content = fs::read_to_string(&path)
        .with_context(|| format!("Failed to read {}", path.display()))?;
    let config: AppConfig = toml::from_str(&content)?;
    Ok(config)
}

Configuring tracing-subscriber for CLIs
A well-behaved CLI suppresses debug noise by default, allowing users to activate granular logs via environment variables (RUST_LOG=debug) or a -v/-vv flag:
use tracing::{info, debug, warn, instrument};
use tracing_subscriber::{fmt, EnvFilter};

pub fn init_observability(verbosity: u8) {
    let default_filter = match verbosity {
        0 =&gt; "warn",
        1 =&gt; "info",
        2 =&gt; "debug",
        _ =&gt; "trace",
    };

    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new(default_filter));

    // Print logs to stderr so stdout remains clean for Unix piping
    fmt()
        .with_env_filter(filter)
        .with_target(false)
        .with_writer(std::io::stderr)
        .init();
}

#[instrument]
pub fn synchronize_database(target: &str) {
    info!(target, "Beginning database synchronization");
    debug!("Resolving network routes...");
    // ...
    info!("Synchronization complete");
}

Progress Bars and Spinners with indicatif
For long-running tasks, indicatif renders multi-progress bars, download speeds, and spinners without corrupting terminal output:
[dependencies]
indicatif = "0.17"
use indicatif::{ProgressBar, ProgressStyle};
use std::thread;
use std::time::Duration;

pub fn execute_with_progress(items: usize) {
    let pb = ProgressBar::new(items as u64);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({eta})")
            .unwrap()
            .progress_chars("#&gt;-"),
    );

    for _ in 0..items {
        thread::sleep(Duration::from_millis(20));
        pb.inc(1);
    }
    pb.finish_with_message("Batch operation complete");
}

