Idiomatic Cross-Platform Patterns in Rust

1. Always Use std::path::PathBuf and Slices
Never concatenate file paths using string formatting like format!("{}/{}", dir, file). Use .join():
use std::path::{Path, PathBuf};

fn resolve_cache_file(base: &Path, name: &str) -&gt; PathBuf {
    base.join("cache").join(name) // Evaluates to \ on Windows and / on Unix
}


2. Normalizing Line Endings
When parsing text data or comparing outputs, strip trailing carriage returns:
fn clean_line(raw: &str) -&gt; &str {
    raw.strip_suffix("\r\n")
       .or_else(|| raw.strip_suffix('\n'))
       .unwrap_or(raw)
}


3. Conditional Compilation with #[cfg(...)]
When accessing OS-specific syscalls (e.g., Unix file permissions or Windows registry entries):
#[cfg(unix)]
fn set_executable_permission(path: &std::path::Path) -&gt; std::io::Result&lt;()&gt; {
    use std::os::unix::fs::PermissionsExt;
    let mut perms = std::fs::metadata(path)?.permissions();
    perms.set_mode(0o755);
    std::fs::set_permissions(path, perms)
}

#[cfg(windows)]
fn set_executable_permission(_path: &std::path::Path) -&gt; std::io::Result&lt;()&gt; {
    // Windows file permissions rely on ACLs and executable extensions (.exe, .bat)
    Ok(())
}

Signal Handling and Graceful Shutdown
When an operator terminates a running utility with Ctrl+C (SIGINT) or Kubernetes sends SIGTERM, the process must clean up temporary files, flush write buffers, and restore the terminal state:
[dependencies]
ctrlc = "3.4"
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        eprintln!("\nInterrupted! Cleaning up before exit...");
        r.store(false, Ordering::SeqCst);
    }).expect("Error setting Ctrl-C handler");

    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_millis(100));
    }

    println!("Graceful shutdown complete.");
}

